import type { Soru } from "../sorular";

export const P01: Soru[] = [
  { id: "p01-001", k: "Uzay", s: "Güneş aslında ne tür bir gök cismidir?", d: "Bir yıldız", y: ["Bir gezegen", "Bir bulutsu"], a: "Güneş, Samanyolu'ndaki yüz milyarlarca yıldızdan biri. Bize çok yakın olduğu için diğerlerinden çok daha parlak görünür." },
  { id: "p01-002", k: "Uzay", s: "Dünya'ya en yakın yıldız hangisidir?", d: "Güneş", y: ["Proxima Centauri", "Sirius"], a: "Güneş'ten sonra bize en yakın yıldız Proxima Centauri'dir. Onun ışığı bize yaklaşık 4,2 yılda ulaşır." },
  { id: "p01-003", k: "Uzay", s: "Güneş enerjisini nasıl üretir?", d: "Çekirdekte nükleer füzyonla", y: ["Kömür gibi yanarak", "Radyoaktif bozunmayla"], a: "Güneş'in çekirdeğinde hidrojen çekirdekleri birleşip helyuma dönüşür. Bu sırada açığa çıkan enerji ışık ve ısı olarak bize ulaşır." },
  { id: "p01-004", k: "Uzay", s: "Güneş en çok hangi elementten oluşur?", d: "Hidrojen", y: ["Demir", "Oksijen"], a: "Güneş'in kütlesinin yaklaşık dörtte üçü hidrojen, kalanının büyük kısmı helyumdur." },
  { id: "p01-005", k: "Uzay", s: "Güneş Sistemi'nin toplam kütlesinin yaklaşık ne kadarı Güneş'tedir?", d: "Yaklaşık yüzde 99,8", y: ["Yaklaşık yüzde 50", "Yaklaşık yüzde 75"], a: "Gezegenler, uydular ve diğer bütün cisimler toplam kütlenin yalnızca binde ikisi kadardır. Bunun da büyük kısmı Jüpiter'e aittir." },
  { id: "p01-006", k: "Uzay", s: "Güneş yaklaşık kaç yaşındadır?", d: "Yaklaşık 4,6 milyar yıl", y: ["Yaklaşık 460 milyon yıl", "Yaklaşık 46 milyar yıl"], a: "Bu yaş, Güneş Sistemi'nin en eski göktaşlarının ölçülmesiyle hesaplanır. Güneş ve gezegenler aşağı yukarı aynı dönemde oluştu." },
  { id: "p01-007", k: "Uzay", s: "Güneş'in görünen yüzeyinin (fotosfer) sıcaklığı yaklaşık kaç derecedir?", d: "Yaklaşık 5.500 °C", y: ["Yaklaşık 550 °C", "Yaklaşık 55 milyon °C"], a: "Yüzey yaklaşık 5.500 derecedir. Çekirdekte ise sıcaklık yaklaşık 15 milyon dereceye çıkar." },
  { id: "p01-008", k: "Uzay", s: "Güneş'in dış atmosferi korona, görünen yüzeyine göre nasıldır?", d: "Çok daha sıcaktır", y: ["Çok daha soğuktur", "Aynı sıcaklıktadır"], a: "Korona bir milyon dereceyi aşar, yani yüzeyden yüzlerce kat sıcaktır. Bunun nedeni hâlâ araştırılan büyük sorulardan biri." },
  { id: "p01-009", k: "Uzay", s: "Güneş lekeleri neden koyu görünür?", d: "Çevrelerinden daha soğuk oldukları için", y: ["Güneş'teki delikler oldukları için", "Gezegenlerin gölgesi oldukları için"], a: "Lekeler, güçlü manyetik alanların ısı akışını kıstığı bölgelerdir. Aslında çok parlaktırlar ama çevrelerine göre koyu görünürler." },
  { id: "p01-010", k: "Uzay", s: "Güneş lekelerinin sayısı yaklaşık kaç yıllık bir döngüyle artıp azalır?", d: "Yaklaşık 11 yıl", y: ["Yaklaşık 1 yıl", "Yaklaşık 100 yıl"], a: "Döngünün zirvesinde lekeler, Güneş patlamaları ve kutup ışıkları artar. Güneş'in manyetik kutupları da her döngüde yer değiştirir." },
  { id: "p01-011", k: "Uzay", s: "Güneş'in çapı Dünya'nınkinin yaklaşık kaç katıdır?", d: "Yaklaşık 109 katı", y: ["Yaklaşık 10 katı", "Yaklaşık 1.000 katı"], a: "Güneş'in çapı yaklaşık 1,4 milyon kilometredir. Hacmine yaklaşık 1,3 milyon Dünya sığabilir." },
  { id: "p01-012", k: "Uzay", s: "Uzaydan bakıldığında Güneş'in ışığı hangi renktedir?", d: "Beyaz", y: ["Sarı", "Turuncu"], a: "Güneş bütün renkleri yayar ve bunların karışımı beyazdır. Bize sarı ya da turuncu görünmesi, ışığın atmosferde saçılmasından kaynaklanır." },
  { id: "p01-013", k: "Uzay", s: "Güneş hangi yıldız türüne girer?", d: "Sarı cüce", y: ["Kırmızı dev", "Beyaz cüce"], a: "Güneş, G tipi bir ana kol yıldızıdır ve halk arasında sarı cüce diye anılır. Samanyolu'ndaki yıldızların çoğu ondan daha küçük ve sönüktür." },
  { id: "p01-014", k: "Uzay", s: "Güneş ömrünün sonunda neye dönüşecek?", d: "Beyaz cüceye", y: ["Kara deliğe", "Nötron yıldızına"], a: "Güneş, kara delik ya da nötron yıldızı olacak kadar kütleli değil. Önce kırmızı deve dönüşecek, sonra dış katmanlarını atıp beyaz cüce olarak kalacak." },
  { id: "p01-015", k: "Uzay", s: "Güneş'in hidrojen yakarak parladığı ana evresinin bitmesine yaklaşık ne kadar var?", d: "Yaklaşık 5 milyar yıl", y: ["Yaklaşık 5 bin yıl", "Yaklaşık 5 milyon yıl"], a: "Güneş bu evrenin kabaca yarısında. Çekirdekteki hidrojen azaldıkça genişleyip kırmızı dev evresine geçecek." },
  { id: "p01-016", k: "Uzay", s: "Güneş'ten uzaya sürekli akan yüklü parçacıklara ne ad verilir?", d: "Güneş rüzgârı", y: ["Kozmik toz", "Işık basıncı"], a: "Güneş rüzgârı saniyede yüzlerce kilometre hızla yayılır ve gezegenlerin çok ötesine kadar uzanır." },
  { id: "p01-017", k: "Uzay", s: "Kutup ışıkları (aurora) nasıl oluşur?", d: "Güneş'ten gelen parçacıklar atmosfere çarpınca", y: ["Kutuplardaki buz ışığı yansıtınca", "Ay ışığı buz kristallerinde kırılınca"], a: "Yüklü parçacıklar manyetik alan boyunca kutuplara yönelir. Atmosferdeki oksijen yeşil ve kırmızı, azot ise mavi-mor ışık yayar." },
  { id: "p01-018", k: "Uzay", s: "Güneş'in hangi bölgesi kendi ekseni etrafında daha hızlı döner?", d: "Ekvatoru", y: ["Kutupları", "Her yeri aynı hızda döner"], a: "Güneş katı olmadığı için farklı enlemleri farklı hızda döner. Ekvatorda bir tur yaklaşık 25 gün, kutuplara yakın yerlerde yaklaşık 35 gün sürer." },
  { id: "p01-019", k: "Uzay", s: "Astronomik birim (AB) neye eşittir?", d: "Dünya-Güneş ortalama uzaklığına", y: ["Bir ışık yılına", "Dünya-Ay uzaklığına"], a: "Bir astronomik birim yaklaşık 150 milyon kilometredir. Güneş Sistemi'ndeki uzaklıklar çoğu zaman bu birimle anlatılır." },
  { id: "p01-020", k: "Uzay", s: "Güneş, Samanyolu'nun merkezi çevresindeki bir turunu yaklaşık ne kadarda tamamlar?", d: "Yaklaşık 230 milyon yılda", y: ["Yaklaşık 230 yılda", "Yaklaşık 230 bin yılda"], a: "Bu süreye galaktik yıl denir. Güneş, ilk dinozorlar ortaya çıktığından beri bu turu ancak bir kez kadar tamamladı." },
  { id: "p01-021", k: "Uzay", s: "Güneş'in maddesi hangi hâldedir?", d: "Plazma", y: ["Katı", "Sıvı"], a: "Güneş'te sıcaklık o kadar yüksektir ki atomlar elektronlarını kaybeder. Bu iyonlaşmış gaza plazma denir; Güneş'in katı bir yüzeyi yoktur." },
  { id: "p01-022", k: "Uzay", s: "Güçlü Güneş fırtınaları Dünya'da en çok neyi etkileyebilir?", d: "Uyduları ve elektrik şebekelerini", y: ["Okyanus akıntılarını", "Deprem sıklığını"], a: "1989'da bir Güneş fırtınası, Kanada'nın Québec bölgesinde saatlerce süren bir elektrik kesintisine yol açtı." },
  { id: "p01-023", k: "Uzay", s: "Güneş'in koronasının içinden geçen ilk uzay aracı hangisidir?", d: "Parker Solar Probe", y: ["Voyager 1", "Hubble"], a: "NASA'nın Parker Solar Probe aracı 2021'de Güneş'in dış atmosferine girdi. Güneş'e en çok yaklaşan insan yapımı cisimdir." },
  { id: "p01-024", k: "Uzay", s: "Tam Güneş tutulmasında Güneş'in hangi katmanı çıplak gözle görünür hâle gelir?", d: "Korona", y: ["Çekirdek", "Konveksiyon bölgesi"], a: "Ay parlak yüzeyi tamamen örtünce, Güneş'in sönük dış atmosferi incecik bir hale gibi görünür. Bu yalnız tam tutulma anında çıplak gözle izlenebilir." },
  { id: "p01-025", k: "Uzay", s: "Heliosfer nedir?", d: "Güneş rüzgârının oluşturduğu dev kabarcık", y: ["Güneş'in en iç katmanı", "Dünya'nın en üst atmosfer katmanı"], a: "Heliosfer, Güneş rüzgârının yıldızlararası ortamı geri ittiği bölgedir. Voyager 1, 2012'de bu sınırı geçen ilk araç oldu." },
  { id: "p01-026", k: "Uzay", s: "Güneş Sistemi neyden oluştu?", d: "Dönen bir gaz ve toz bulutundan", y: ["Dünya'dan kopan parçalardan", "Jüpiter'in patlamasından"], a: "Bulut kendi kütleçekimiyle çöktü; merkezde Güneş, çevresindeki diskte gezegenler oluştu. Gezegenlerin aynı yönde dolanması bu diskten kalan bir iz." },
  { id: "p01-027", k: "Uzay", s: "Güneş'in yüzeyindeki kütleçekimi, Dünya'nınkinin yaklaşık kaç katıdır?", d: "Yaklaşık 28 katı", y: ["Yaklaşık 2 katı", "Yaklaşık 280 katı"], a: "Dünya'da 70 kilogram gelen biri, Güneş'in yüzeyinde durabilseydi kendini yaklaşık 2 ton ağırlığında hissederdi." },
  { id: "p01-028", k: "Uzay", s: "Güneş'in ışığı Plüton'a yaklaşık ne kadar sürede ulaşır?", d: "Yaklaşık 5,5 saatte", y: ["Yaklaşık 5,5 dakikada", "Yaklaşık 5,5 günde"], a: "Plüton, Güneş'e Dünya'dan ortalama yaklaşık 40 kat daha uzaktır. Orada öğle vakti bile Dünya'daki alacakaranlığa benzer." },
  { id: "p01-029", k: "Uzay", s: "Güneş'e çıplak gözle bakmak neden tehlikelidir?", d: "Retinaya kalıcı zarar verebilir", y: ["Yalnız geçici kamaşma yapar", "Yalnız göz kuruluğu yapar"], a: "Güneş'e kısa süre bile doğrudan bakmak retinayı yakabilir. Tutulmaları izlerken özel tutulma gözlüğü gerekir; güneş gözlüğü yetmez." },
  { id: "p01-030", k: "Uzay", s: "SOHO uzay gözlemevi, Güneş'i incelemenin yanında neyi keşfetmesiyle de ünlüdür?", d: "Binlerce kuyruklu yıldızı", y: ["Onlarca yeni gezegeni", "Yakındaki kara delikleri"], a: "1995'te fırlatılan SOHO, Güneş'e çok yaklaşan binlerce kuyruklu yıldızı görüntüledi. Tarihte en çok kuyruklu yıldız keşfeden araçtır." },
  { id: "p01-031", k: "Uzay", s: "Güneş'te her saniye yaklaşık ne kadar kütle enerjiye dönüşür?", d: "Yaklaşık 4 milyon ton", y: ["Yaklaşık 4 kilogram", "Yaklaşık 4 ton"], a: "Bu dev rakama rağmen Güneş o kadar büyüktür ki milyarlarca yılda kütlesinin yalnız çok küçük bir kısmını kaybeder." },
  { id: "p01-032", k: "Uzay", s: "Dünya'dan önce Güneş'te keşfedilen element hangisidir?", d: "Helyum", y: ["Hidrojen", "Neon"], a: "Helyum 1868'de Güneş ışığının tayfında fark edildi ve adını Yunanca Güneş anlamına gelen 'helios'tan aldı. Dünya'da ancak yıllar sonra bulundu." },
  { id: "p01-033", k: "Uzay", s: "Kuzey Yarımküre'de yılın en uzun günü hangi aydadır?", d: "Haziran", y: ["Aralık", "Mart"], a: "Yaz gün dönümü 20-21 Haziran civarına denk gelir. Aynı gün Güney Yarımküre'de yılın en kısa günü yaşanır." },
  { id: "p01-034", k: "Uzay", s: "Gece ile gündüzün yaklaşık eşit olduğu günlere ne denir?", d: "Ekinoks", y: ["Gün dönümü", "Günberi"], a: "Ekinokslar Mart ve Eylül'de yaşanır. Bu günlerde Güneş doğudan doğar, batıdan batar ve bütün dünyada gündüz yaklaşık 12 saat sürer." },
  { id: "p01-035", k: "Uzay", s: "Dünya'nın yörüngesinde Güneş'e en yakın olduğu noktaya ne denir?", d: "Günberi", y: ["Günöte", "Yerberi"], a: "Dünya günberiye her yıl Ocak başında, en uzak nokta olan günöteye ise Temmuz başında ulaşır. Aradaki fark yaklaşık 5 milyon kilometredir." },
  { id: "p01-036", k: "Uzay", s: "Güneş'e en yakın gezegen hangisidir?", d: "Merkür", y: ["Venüs", "Mars"], a: "Merkür, Güneş'e ortalama yaklaşık 58 milyon kilometre uzaklıktadır. Bu, Dünya'nın Güneş'e uzaklığının yaklaşık beşte ikisidir." },
  { id: "p01-037", k: "Uzay", s: "Güneş Sistemi'nin en küçük gezegeni hangisidir?", d: "Merkür", y: ["Mars", "Venüs"], a: "Merkür, Ay'dan yalnızca biraz büyüktür. Plüton 2006'da cüce gezegen sayılınca en küçük gezegen unvanı Merkür'e geçti." },
  { id: "p01-038", k: "Uzay", s: "Merkür'de bir yıl yaklaşık kaç Dünya günü sürer?", d: "Yaklaşık 88 gün", y: ["Yaklaşık 365 gün", "Yaklaşık 8 gün"], a: "Merkür, Güneş çevresinde en hızlı dolanan gezegendir; saniyede yaklaşık 47 kilometre yol alır." },
  { id: "p01-039", k: "Uzay", s: "Merkür'de bir gün doğumundan sonrakine kadar yaklaşık ne kadar zaman geçer?", d: "Yaklaşık 176 Dünya günü", y: ["Yaklaşık 24 saat", "Yaklaşık 10 Dünya günü"], a: "Merkür'de bir güneş günü, iki Merkür yılı kadar sürer. Gezegen kendi ekseninde yavaş döndüğü ve hızlı dolandığı için gün yıldan uzundur." },
  { id: "p01-040", k: "Uzay", s: "Merkür'de gündüz ile gece arasındaki sıcaklık farkı neden çok büyüktür?", d: "Atmosferi yok denecek kadar ince", y: ["Yüzeyi tamamen buzla kaplı", "Çekirdeği tamamen soğumuş"], a: "Merkür'de gündüz sıcaklık yaklaşık 430 °C'ye çıkar, gece eksi 180 °C'ye kadar düşer." },
  { id: "p01-041", k: "Uzay", s: "Merkür'ün kutuplarındaki hiç Güneş görmeyen kraterlerde ne bulundu?", d: "Su buzu", y: ["Sıvı lav gölleri", "Fosil izleri"], a: "Bu kraterlerin dibi sürekli gölgede ve çok soğuktur. NASA'nın MESSENGER aracı buradaki buzun güçlü kanıtlarını buldu." },
  { id: "p01-042", k: "Uzay", s: "Merkür'ün yörüngesine giren ilk uzay aracı hangisidir?", d: "MESSENGER", y: ["Voyager 2", "Cassini"], a: "NASA'nın MESSENGER aracı 2011'de Merkür yörüngesine girdi ve gezegeni dört yıl boyunca haritaladı." },
  { id: "p01-043", k: "Uzay", s: "Hangi uydu, Merkür gezegeninden daha büyük çaplıdır?", d: "Ganymede", y: ["Ay", "Europa"], a: "Jüpiter'in uydusu Ganymede, Güneş Sistemi'nin en büyük uydusudur. Satürn'ün uydusu Titan da Merkür'den büyüktür." },
  { id: "p01-044", k: "Uzay", s: "Merkür'ün yüzeyi en çok hangi gök cismininkine benzer?", d: "Ay'ınkine", y: ["Dünya'nınkine", "Venüs'ünkine"], a: "Merkür de Ay gibi kraterlerle kaplıdır. En büyük çarpma havzalarından Caloris'in çapı yaklaşık 1.500 kilometredir." },
  { id: "p01-045", k: "Uzay", s: "Merkür'ü çıplak gözle görmek neden zordur?", d: "Gökyüzünde hep Güneş'e yakın durduğu için", y: ["Çok sönük bir gezegen olduğu için", "Yalnız Güney Yarımküre'den göründüğü için"], a: "Merkür yalnız gün doğumundan hemen önce ya da gün batımından hemen sonra, ufka yakın görülebilir. Aslında oldukça parlaktır." },
  { id: "p01-046", k: "Uzay", s: "Merkür, büyüklüğüne oranla hangi özelliğiyle dikkat çeker?", d: "Çok büyük bir metal çekirdeği", y: ["Kalın bir buz kabuğu", "Dev bir gaz atmosferi"], a: "Merkür'ün çekirdeği yarıçapının beşte dördünden fazlasını kaplar. Bu yüzden Dünya'dan sonra en yoğun ikinci gezegendir." },
  { id: "p01-047", k: "Uzay", s: "Merkür ve Venüs'ün ortak özelliği hangisidir?", d: "İkisinin de uydusu yok", y: ["İkisinin de halkası var", "İkisi de gaz devi"], a: "Güneş'e en yakın bu iki gezegenin uydusu yoktur. Güneş'ten dışarı doğru uydusu olan ilk gezegen Dünya'dır." },
  { id: "p01-048", k: "Uzay", s: "Merkür, Güneş'in önünden geçerken Dünya'dan nasıl görünür?", d: "Küçük siyah bir nokta gibi", y: ["Parlak bir halka gibi", "Güneş'i tamamen örten bir disk gibi"], a: "Bu olaya Merkür geçişi denir ve yüzyılda yaklaşık 13 kez yaşanır. Gezegen, Güneş diskinin önünde saatlerce yavaşça ilerler." },
  { id: "p01-049", k: "Uzay", s: "Venüs kendi ekseni etrafında hangi yönde döner?", d: "Çoğu gezegenin tersine", y: ["Dünya ile aynı yönde", "Hiç dönmez"], a: "Venüs ters yönde döndüğü için orada Güneş batıdan doğar, doğudan batar." },
  { id: "p01-050", k: "Uzay", s: "Venüs'ün kendi ekseninde bir kez dönmesi, Güneş çevresindeki turundan uzun mu sürer?", d: "Evet, daha uzun sürer", y: ["Hayır, çok daha kısa sürer", "İkisi tam olarak eşittir"], a: "Venüs kendi çevresinde yaklaşık 243 Dünya gününde döner. Güneş çevresindeki turu ise yaklaşık 225 gün sürer." },
  { id: "p01-051", k: "Uzay", s: "Venüs'ün atmosferi en çok hangi gazdan oluşur?", d: "Karbondioksit", y: ["Azot", "Oksijen"], a: "Venüs atmosferinin yaklaşık yüzde 96'sı karbondioksittir. Bu kalın örtü çok güçlü bir sera etkisi yaratır." },
  { id: "p01-052", k: "Uzay", s: "Venüs'ün bulutları neyden oluşur?", d: "Sülfürik asit damlacıklarından", y: ["Su buharından", "Metan buzundan"], a: "Bu kalın bulutlar Güneş ışığının çoğunu geri yansıtır. Venüs'ün gökyüzünde bu kadar parlak görünmesinin nedeni de budur." },
  { id: "p01-053", k: "Uzay", s: "Venüs'ün yüzeyindeki atmosfer basıncı Dünya'dakinin yaklaşık kaç katıdır?", d: "Yaklaşık 90 katı", y: ["Yaklaşık yarısı", "Yaklaşık 2 katı"], a: "Bu basınç, Dünya okyanuslarında yaklaşık 900 metre derinlikte hissedilen basınca eşittir." },
  { id: "p01-054", k: "Uzay", s: "Boyut ve kütlece Dünya'ya en çok benzeyen gezegen hangisidir?", d: "Venüs", y: ["Mars", "Merkür"], a: "Bu benzerlik yüzünden Venüs'e Dünya'nın ikizi denir. Ama kalın atmosferi yüzünden yüzeyi yaşama son derece elverişsizdir." },
  { id: "p01-055", k: "Uzay", s: "Güneş ve Ay'dan sonra gökyüzündeki en parlak doğal cisim hangisidir?", d: "Venüs", y: ["Sirius", "Kutup Yıldızı"], a: "Venüs o kadar parlaktır ki nereye bakılacağı bilinirse gündüz bile görülebilir. Gece gökyüzünün en parlak yıldızı ise Sirius'tur." },
  { id: "p01-056", k: "Uzay", s: "Halk arasında 'Çoban Yıldızı' denen parlak gök cismi aslında nedir?", d: "Venüs gezegeni", y: ["Kutup Yıldızı", "Sirius yıldızı"], a: "Venüs, gün batımından sonra batıda ya da gün doğumundan önce doğuda parlar. Bu yüzden Akşam Yıldızı ve Sabah Yıldızı diye de anılır." },
  { id: "p01-057", k: "Uzay", s: "Venüs yüzeyine inen ilk uzay araçlarını hangi ülke gönderdi?", d: "Sovyetler Birliği", y: ["ABD", "Japonya"], a: "Sovyet Venera araçları 1970'lerde Venüs'e indi ve yüzeyden ilk fotoğrafları gönderdi. Ağır koşullar yüzünden ancak kısa süre dayanabildiler." },
  { id: "p01-058", k: "Uzay", s: "Venüs'ün yüzeyi Dünya'dan teleskopla neden görülemez?", d: "Kalın bulutlarla örtülü olduğu için", y: ["Hep Güneş'in arkasında kaldığı için", "Yüzeyi ışığı tamamen yuttuğu için"], a: "Venüs'ün yüzeyi ancak bulutları delen radarla haritalanabildi. NASA'nın Magellan aracı 1990'larda yüzeyin neredeyse tamamını böyle çıkardı." },
  { id: "p01-059", k: "Uzay", s: "Galileo, Venüs'te neyi gözleyerek Güneş merkezli modeli destekledi?", d: "Ay gibi evreleri olduğunu", y: ["Uyduları olduğunu", "Halkası olduğunu"], a: "Venüs'ün ince hilalden neredeyse dolunaya kadar evreler göstermesi, onun Güneş'in çevresinde dolandığını ortaya koydu." },
  { id: "p01-060", k: "Uzay", s: "Dünya'ya en fazla yaklaşan gezegen hangisidir?", d: "Venüs", y: ["Mars", "Jüpiter"], a: "Venüs en yakın konumunda Dünya'ya yaklaşık 40 milyon kilometreye kadar yaklaşır. Mars'ın en yakın geçişleri ise yaklaşık 55 milyon kilometre civarındadır." },
  { id: "p01-061", k: "Uzay", s: "Venüs'ün Güneş'in önünden geçişi hangi düzende yaşanır?", d: "Sekiz yıl arayla çiftler hâlinde", y: ["Her yıl bir kez", "Her on bir yılda bir"], a: "Son Venüs geçişleri 2004 ve 2012'de yaşandı. Bir sonraki çift 2117 ve 2125 yıllarında gerçekleşecek." },
  { id: "p01-062", k: "Uzay", s: "Dünya, Güneş'ten itibaren kaçıncı gezegendir?", d: "Üçüncü", y: ["İkinci", "Dördüncü"], a: "Dünya, yüzeyinde kalıcı sıvı su okyanusları bulunan ve yaşam barındırdığı bilinen tek gök cismidir." },
  { id: "p01-063", k: "Uzay", s: "Dünya, Güneş çevresinde yaklaşık hangi hızla dolanır?", d: "Saniyede yaklaşık 30 km", y: ["Saniyede yaklaşık 3 km", "Saniyede yaklaşık 300 km"], a: "Bu, saatte yaklaşık 107 bin kilometre eder. Yine de hareketi hissetmeyiz, çünkü hızımız neredeyse sabittir." },
  { id: "p01-064", k: "Uzay", s: "Şubat ayına dört yılda bir fazladan bir gün neden eklenir?", d: "Bir yıl yaklaşık 365,25 gün sürdüğü için", y: ["Ay'ın yörüngesi kısaldığı için", "Dünya'nın dönüşü hızlandığı için"], a: "Her yıl artan yaklaşık çeyrek gün, dört yılda bir tam güne ulaşır. Bu yüzden takvime 29 Şubat eklenir." },
  { id: "p01-065", k: "Uzay", s: "Dünya, yıldızlara göre kendi ekseni çevresindeki bir turu yaklaşık ne kadarda tamamlar?", d: "23 saat 56 dakikada", y: ["Tam 24 saatte", "25 saat 4 dakikada"], a: "Buna yıldız günü denir. Güneş'in gökte aynı noktaya gelmesi için Dünya'nın biraz daha dönmesi gerekir; güneş günü bu yüzden 24 saattir." },
  { id: "p01-066", k: "Uzay", s: "Dünya kusursuz bir küre midir?", d: "Hayır, ekvatordan biraz şişkindir", y: ["Evet, kusursuz bir küredir", "Hayır, kutuplardan şişkindir"], a: "Dönüşün etkisiyle Dünya'nın ekvator çapı, kutuptan kutba çapından yaklaşık 43 kilometre fazladır." },
  { id: "p01-067", k: "Uzay", s: "Dünya'nın kütleçekiminden kurtulmak için gereken kaçış hızı yaklaşık ne kadardır?", d: "Saniyede yaklaşık 11,2 km", y: ["Saniyede yaklaşık 1,1 km", "Saniyede yaklaşık 112 km"], a: "Kaçış hızı gök cisminin kütlesine ve boyutuna bağlıdır. Ay'da bu değer saniyede yalnızca yaklaşık 2,4 kilometredir." },
  { id: "p01-068", k: "Uzay", s: "Bir yıldızın çevresinde, gezegen yüzeyinde suyun sıvı kalabileceği bölgeye ne denir?", d: "Yaşanabilir bölge", y: ["Asteroit kuşağı", "Kuiper kuşağı"], a: "Bu bölgede su ne donar ne de tamamen buharlaşır. Güneş Sistemi'nde Dünya bu bölgenin içindedir." },
  { id: "p01-069", k: "Uzay", s: "Güneş Sistemi'ndeki kayalık gezegenlerin en büyüğü hangisidir?", d: "Dünya", y: ["Venüs", "Mars"], a: "Merkür, Venüs, Dünya ve Mars kayalık gezegenlerdir. Dünya, Venüs'ten yalnızca biraz daha büyüktür." },
  { id: "p01-070", k: "Uzay", s: "Ay'ın Dünya'ya ortalama uzaklığı yaklaşık ne kadardır?", d: "Yaklaşık 384 bin km", y: ["Yaklaşık 38 bin km", "Yaklaşık 3,8 milyon km"], a: "Ay'dan yansıyan ışık bize yaklaşık 1,3 saniyede ulaşır. Apollo astronotlarının Ay'a yolculuğu ise yaklaşık 3 gün sürdü." },
  { id: "p01-071", k: "Uzay", s: "Ay'ın çapı Dünya'nınkinin yaklaşık ne kadarıdır?", d: "Yaklaşık dörtte biri", y: ["Yaklaşık yarısı", "Yaklaşık onda biri"], a: "Ay'ın çapı yaklaşık 3.475 kilometredir. Gezegenine oranla Güneş Sistemi'nin en büyük uydularından biridir." },
  { id: "p01-072", k: "Uzay", s: "Ay'daki kütleçekimi Dünya'dakinin yaklaşık ne kadarıdır?", d: "Yaklaşık altıda biri", y: ["Yaklaşık yarısı", "Yaklaşık yüzde biri"], a: "Dünya'da 60 kilogram gelen biri Ay'da kendini 10 kilogram gibi hisseder. Apollo astronotları bu yüzden sekerek yürüdü." },
  { id: "p01-073", k: "Uzay", s: "Ay neden Dünya'ya hep aynı yüzünü gösterir?", d: "Kendi ekseninde ve Dünya çevresinde aynı sürede döner", y: ["Kendi ekseni çevresinde hiç dönmez", "Dünya'nın gölgesi öbür yüzünü gizler"], a: "Buna kütleçekimsel kilitlenme denir. Dünya'nın gelgit etkisi, Ay'ın dönüşünü zamanla yörünge süresine eşitledi." },
  { id: "p01-074", k: "Uzay", s: "Ay'ın 'karanlık yüzü' denen uzak yüzü gerçekten hep karanlık mıdır?", d: "Hayır, o da Güneş ışığı alır", y: ["Evet, hiç Güneş görmez", "Yalnız tutulmalarda aydınlanır"], a: "Uzak yüz yalnızca Dünya'dan görünmez. Yeni Ay evresinde bize dönük yüz karanlıkken uzak yüz tamamen aydınlıktır." },
  { id: "p01-075", k: "Uzay", s: "Ay evrelerinin tam döngüsü, yani bir dolunaydan ötekine kadar geçen süre yaklaşık ne kadardır?", d: "Yaklaşık 29,5 gün", y: ["Yaklaşık 14 gün", "Yaklaşık 40 gün"], a: "Ay, yıldızlara göre turunu yaklaşık 27,3 günde tamamlar. Bu arada Dünya da Güneş çevresinde ilerlediği için evre döngüsü iki gün kadar uzun sürer." },
  { id: "p01-076", k: "Uzay", s: "Ay ışığı aslında nedir?", d: "Ay'dan yansıyan Güneş ışığı", y: ["Ay'ın kendi ürettiği ışık", "Ay kayalarının ısıdan parlaması"], a: "Ay'ın yüzeyi, üzerine düşen ışığın yalnız yaklaşık sekizde birini yansıtır. Yani aslında eski bir asfalt kadar koyu bir yüzeydir." },
  { id: "p01-077", k: "Uzay", s: "Ay neden bazen ince bir hilal şeklinde görünür?", d: "Aydınlık yarısının az bir kısmını gördüğümüz için", y: ["Dünya'nın gölgesi üstüne düştüğü için", "Bulutlar bir kısmını örttüğü için"], a: "Ay'ın her zaman yarısı Güneş'le aydınlanır. Evreler, bu aydınlık yarının ne kadarını gördüğümüze bağlıdır; Dünya'nın gölgesi yalnız tutulmalarda devreye girer." },
  { id: "p01-078", k: "Uzay", s: "Yeni Ay evresinde Ay nerededir?", d: "Dünya ile Güneş'in arasında", y: ["Dünya'nın Güneş'e göre arkasında", "Dünya'nın gölgesinin içinde"], a: "Bu evrede Ay'ın aydınlık yüzü Güneş'e, karanlık yüzü bize dönüktür. Ay, Güneş'le aşağı yukarı birlikte doğup battığı için görünmez." },
  { id: "p01-079", k: "Uzay", s: "Dolunay evresinde Ay, Güneş'e göre nerededir?", d: "Dünya'nın karşı tarafında", y: ["Dünya ile Güneş'in arasında", "Gökte Güneş'in hemen yanında"], a: "Dolunay, Güneş batarken doğar ve gece yarısı gökyüzünde en yüksek noktasına çıkar." },
  { id: "p01-080", k: "Uzay", s: "Yeni Ay'dan hemen sonra gelen evre hangisidir?", d: "Büyüyen hilal", y: ["İlk dördün", "Dolunay"], a: "Sıra şöyledir: Yeni Ay, büyüyen hilal, ilk dördün, şişkin Ay, dolunay. Sonra Ay aynı evrelerden geriye doğru geçer." },
  { id: "p01-081", k: "Uzay", s: "İlk dördün evresinde Ay'ın görünen yüzünün ne kadarı aydınlıktır?", d: "Yaklaşık yarısı", y: ["Yaklaşık dörtte biri", "Tamamı"], a: "Adı 'dördün' olsa da bu evrede Ay'ın yarısı aydınlık görünür. Ay, evre döngüsünün dörtte birini tamamladığı için bu adı alır." },
  { id: "p01-082", k: "Uzay", s: "Kuzey Yarımküre'den bakınca büyüyen hilalin hangi tarafı aydınlıktır?", d: "Sağ tarafı", y: ["Sol tarafı", "Alt tarafı"], a: "Kuzey Yarımküre'de büyüyen Ay sağdan, küçülen Ay soldan aydınlık görünür. Güney Yarımküre'de durum tersine döner." },
  { id: "p01-083", k: "Uzay", s: "Ay gündüz gökyüzünde görülebilir mi?", d: "Evet, ayın birçok gününde", y: ["Hayır, yalnız gece görünür", "Yalnız tutulma günlerinde"], a: "Ay, evresine göre günün farklı saatlerinde doğar. İlk dördün civarında öğleden sonra, son dördün civarında sabah gökyüzünde kolayca görülür." },
  { id: "p01-084", k: "Uzay", s: "'Süper Ay' ne demektir?", d: "Dünya'ya yakınken görülen dolunay", y: ["Yılın ilk dolunayı", "Tutulma sırasındaki Ay"], a: "Ay'ın yörüngesi elips olduğu için uzaklığı değişir. Yakın noktadaki dolunay, en uzaktaki dolunaydan yaklaşık yüzde 14 büyük görünür." },
  { id: "p01-085", k: "Uzay", s: "Halk arasındaki 'Mavi Ay' ifadesi en çok neyi anlatır?", d: "Bir takvim ayındaki ikinci dolunayı", y: ["Mavi renkte görünen Ay'ı", "Tutulma sırasındaki Ay'ı"], a: "Mavi Ay birkaç yılda bir yaşanır ve Ay'ın rengi değişmez. Ay ancak havada belli boyutta duman ya da kül olduğunda mavimsi görünebilir." },
  { id: "p01-086", k: "Uzay", s: "Ay her yıl Dünya'dan yaklaşık ne kadar uzaklaşıyor?", d: "Yaklaşık 3,8 santimetre", y: ["Yaklaşık 3,8 metre", "Yaklaşık 38 metre"], a: "Bu ölçüm, Apollo astronotlarının Ay'a bıraktığı aynalara lazer gönderilerek yapılır. Uzaklaşmanın nedeni Dünya ile Ay arasındaki gelgit etkileşimidir." },
  { id: "p01-087", k: "Uzay", s: "Ay'ın oluşumu için en çok kabul gören açıklama hangisidir?", d: "Genç Dünya'ya dev bir cismin çarpması", y: ["Dünya'nın kendi kendine ikiye bölünmesi", "Güneş'ten kopan bir parça"], a: "Bu görüşe göre Mars büyüklüğünde bir cisim genç Dünya'ya çarptı ve saçılan malzeme birleşip Ay'ı oluşturdu. Bu cisme Theia adı verilir." },
  { id: "p01-088", k: "Uzay", s: "Ay'a ayak basan ilk insan kimdir?", d: "Neil Armstrong", y: ["Yuri Gagarin", "Buzz Aldrin"], a: "Apollo 11 aracı 20 Temmuz 1969'da Ay'a indi ve Armstrong yüzeye ilk adımı attı. Buzz Aldrin kısa süre sonra ona katıldı." },
  { id: "p01-089", k: "Uzay", s: "Apollo 11 görevinde yörüngede kalıp Ay'a inmeyen astronot kimdir?", d: "Michael Collins", y: ["Buzz Aldrin", "John Glenn"], a: "Collins, arkadaşları yüzeydeyken komuta modülünü Ay yörüngesinde uçurdu. Ay'ın arkasına her geçişinde Dünya ile bağlantısı kesiliyordu." },
  { id: "p01-090", k: "Uzay", s: "Ay yüzeyinde toplam kaç kişi yürüdü?", d: "12", y: ["6", "30"], a: "Altı Apollo görevi 1969-1972 arasında Ay'a indi ve her birinde iki astronot yüzeyde yürüdü." },
  { id: "p01-091", k: "Uzay", s: "Apollo programında Ay'a inen son görev hangisidir?", d: "Apollo 17", y: ["Apollo 13", "Apollo 11"], a: "Apollo 17 Aralık 1972'de Ay'a indi. Astronotlar Ay yüzeyinde üç günden fazla kaldı." },
  { id: "p01-092", k: "Uzay", s: "Apollo 13 görevi neden Ay'a inemedi?", d: "Bir oksijen tankı patladı", y: ["Roket fırlatmada düştü", "Astronotlar hastalandı"], a: "Mürettebat, Ay modülünü cankurtaran gibi kullanıp Ay'ın çevresinden dolaştı ve Dünya'ya sağ salim döndü." },
  { id: "p01-093", k: "Uzay", s: "Ay'daki ayak izleri neden çok uzun süre bozulmadan kalabilir?", d: "Rüzgâr ve su olmadığı için", y: ["Ay toprağı beton gibi sertleştiği için", "Ay'a hiç göktaşı düşmediği için"], a: "Ay'da izleri silecek hava ya da su yoktur. Yine de çok uzun sürede küçük göktaşı çarpmaları izleri yavaş yavaş bozar." },
  { id: "p01-094", k: "Uzay", s: "Ay'da gündüz gökyüzü hangi renktedir?", d: "Siyah", y: ["Mavi", "Turuncu"], a: "Ay'da ışığı saçacak bir atmosfer yoktur. Bu yüzden Güneş tepedeyken bile gökyüzü simsiyah görünür." },
  { id: "p01-095", k: "Uzay", s: "Ay'daki koyu, düz bölgeler neyden oluşur?", d: "Katılaşmış lavdan", y: ["Kurumuş deniz tabanından", "Buz tabakalarından"], a: "Eski gökbilimciler bu düzlükleri deniz sandı ve Latince 'maria' (denizler) adını verdi. Aslında milyarlarca yıl önce akmış bazalt lavlarıdır." },
  { id: "p01-096", k: "Uzay", s: "Ay'ın uzak yüzünü ilk kez fotoğraflayan uzay aracı hangisidir?", d: "Luna 3", y: ["Apollo 8", "Voyager 1"], a: "Sovyet aracı Luna 3, 1959'da uzak yüzün ilk fotoğraflarını çekti. Bu yüzde koyu düzlüklerin çok daha az olduğu anlaşıldı." },
  { id: "p01-097", k: "Uzay", s: "Ay'ın uzak yüzüne ilk yumuşak inişi hangi ülke yaptı?", d: "Çin", y: ["ABD", "Rusya"], a: "Çin'in Chang'e 4 aracı 2019'da Ay'ın uzak yüzüne indi. Dünya ile iletişim, Ay'ın arkasını gören bir aktarma uydusuyla sağlandı." },
  { id: "p01-098", k: "Uzay", s: "Ay'a ulaşan ilk insan yapımı cisim hangisidir?", d: "Luna 2", y: ["Apollo 11", "Sputnik 1"], a: "Sovyet aracı Luna 2, 1959'da Ay yüzeyine çarptı. Başka bir gök cismine ulaşan ilk insan yapımı nesne oldu." },
  { id: "p01-099", k: "Uzay", s: "Ay yüzeyinde gündüz ve gece sıcaklıkları yaklaşık nasıldır?", d: "Yaklaşık 120 °C ile eksi 130 °C", y: ["Yaklaşık 20 °C ile 0 °C", "Gece gündüz eksi 270 °C"], a: "Ay'da ısıyı dengeleyecek atmosfer yoktur. Ayrıca bir Ay günü yaklaşık 29,5 Dünya günü sürdüğü için her yer iki hafta kadar Güneş altında kalır." },
  { id: "p01-100", k: "Uzay", s: "Ay, Güneş Sistemi'ndeki uydular arasında büyüklükte kaçıncı sıradadır?", d: "Beşinci", y: ["Birinci", "Onuncu"], a: "Ay'dan büyük dört uydu Ganymede, Titan, Callisto ve Io'dur. Ay, kayalık gezegenlerin uyduları arasında açık ara en büyüğüdür." },
  { id: "p01-101", k: "Uzay", s: "Güneş tutulması hangi Ay evresinde olabilir?", d: "Yeni Ay", y: ["Dolunay", "İlk dördün"], a: "Güneş tutulmasında Ay, Dünya ile Güneş'in arasına girer. Bu hiza yalnız Yeni Ay evresinde mümkündür." },
  { id: "p01-102", k: "Uzay", s: "Ay tutulması hangi Ay evresinde olabilir?", d: "Dolunay", y: ["Yeni Ay", "Son dördün"], a: "Ay tutulmasında Dünya, Güneş ile Ay'ın arasına girer ve gölgesini Ay'ın üzerine düşürür." },
  { id: "p01-103", k: "Uzay", s: "Tam Ay tutulmasında Ay neden kızıl görünür?", d: "Dünya atmosferinden geçen ışık yüzünden", y: ["Ay'ın yüzeyi ısınıp parladığı için", "Mars'ın ışığını yansıttığı için"], a: "Dünya'nın atmosferi mavi ışığı saçar, kırmızı ışığı ise bükerek gölgenin içine yollar. Ay'a sanki Dünya'daki bütün gün doğumu ve batımlarının ışığı düşer." },
  { id: "p01-104", k: "Uzay", s: "Neden her ay bir Güneş tutulması ve bir Ay tutulması olmaz?", d: "Ay'ın yörüngesi biraz eğik olduğu için", y: ["Ay her ay farklı hızda döndüğü için", "Güneş bazı aylarda küçüldüğü için"], a: "Ay'ın yörüngesi, Dünya'nın yörünge düzlemine göre yaklaşık 5 derece eğiktir. Bu yüzden üç gök cismi çoğu zaman tam hizaya gelmez." },
  { id: "p01-105", k: "Uzay", s: "Ay, Güneş'ten çok küçük olduğu hâlde onu nasıl tamamen örtebilir?", d: "Güneş yaklaşık 400 kat uzakta olduğu için", y: ["Ay aslında Güneş'ten büyük olduğu için", "Atmosfer Güneş'i küçük gösterdiği için"], a: "Güneş'in çapı Ay'ınkinin yaklaşık 400 katıdır ama bize yaklaşık 400 kat daha uzaktır. Bu tesadüf sayesinde ikisi gökte neredeyse aynı büyüklükte görünür." },
  { id: "p01-106", k: "Uzay", s: "Halkalı Güneş tutulması neden olur?", d: "Ay uzak olduğu için Güneş'i tam örtemez", y: ["Ay'ın çevresinde bir halka vardır", "Dünya'nın gölgesi Güneş'e düşer"], a: "Ay yörüngesinin uzak kısmındayken gökte biraz küçük görünür. Güneş'in ortasını örter ama kenarları parlak bir halka gibi açıkta kalır." },
  { id: "p01-107", k: "Uzay", s: "Tam Güneş tutulmasının tam karanlık evresi bir yerde en fazla ne kadar sürebilir?", d: "Yaklaşık 7,5 dakika", y: ["Yaklaşık 1 saat", "Yaklaşık 3 saat"], a: "Çoğu tam tutulmada bu evre birkaç dakika sürer. Ay'ın gölgesi yeryüzünde saatte bin kilometreyi aşan bir hızla ilerler." },
  { id: "p01-108", k: "Uzay", s: "Tam Güneş tutulmasını neden yalnız dar bir şeritteki insanlar görebilir?", d: "Ay'ın tam gölgesi küçük bir alana düştüğü için", y: ["Bulutlar diğer yerleri kapattığı için", "Güneş yalnız o bölgede doğduğu için"], a: "Ay'ın tam gölgesi yeryüzünde en fazla birkaç yüz kilometre genişliğinde bir şerit çizer. Bu şeridin dışındakiler yalnız parçalı tutulma görür." },
  { id: "p01-109", k: "Uzay", s: "Bir Ay tutulması Dünya'nın neresinden izlenebilir?", d: "O sırada gece olan her yerden", y: ["Yalnız ekvatordan", "Yalnız dar bir şeritten"], a: "Ay tutulmasında Ay gerçekten Dünya'nın gölgesine girer. Bu yüzden o sırada Ay'ı görebilen herkes tutulmayı da görür." },
  { id: "p01-110", k: "Uzay", s: "Ay tutulmasını çıplak gözle izlemek güvenli midir?", d: "Evet, tamamen güvenlidir", y: ["Hayır, özel gözlük gerekir", "Yalnız teleskopla güvenlidir"], a: "Ay tutulmasında bakılan şey Ay'dır ve Ay'ın ışığı göze zarar vermez. Özel gözlük yalnız Güneş tutulmaları için gereklidir." },
  { id: "p01-111", k: "Uzay", s: "Okyanuslardaki gelgitlere asıl ne neden olur?", d: "Ay'ın ve Güneş'in kütleçekimi", y: ["Rüzgârların denizi itmesi", "Dünya'nın iç ısısı"], a: "Ay, Dünya'nın kendisine yakın ve uzak taraflarını farklı kuvvetle çeker. Bu fark okyanusları iki yandan kabartır." },
  { id: "p01-112", k: "Uzay", s: "Çoğu kıyıda günde kaç kez yüksek su (kabarma) olur?", d: "İki kez", y: ["Bir kez", "Dört kez"], a: "Okyanuslarda biri Ay'a bakan, öteki tam karşı tarafta olan iki kabarıklık oluşur. Dünya döndükçe kıyılar bu iki kabarıklığın içinden geçer." },
  { id: "p01-113", k: "Uzay", s: "Ardışık iki yüksek su arasında yaklaşık ne kadar zaman geçer?", d: "Yaklaşık 12 saat 25 dakika", y: ["Yaklaşık 3 saat", "Yaklaşık 2 gün"], a: "Ay her gün bir önceki güne göre yaklaşık 50 dakika geç doğar. Bu yüzden gelgit saatleri de her gün kayar." },
  { id: "p01-114", k: "Uzay", s: "En güçlü gelgitler hangi Ay evrelerinde görülür?", d: "Yeni Ay ve dolunayda", y: ["İlk ve son dördünde", "Yalnız şişkin Ay'da"], a: "Bu evrelerde Güneş, Dünya ve Ay aynı hizadadır ve çekim etkileri toplanır. Dördün evrelerinde birbirini kısmen dengeler; gelgit zayıflar." },
  { id: "p01-115", k: "Uzay", s: "Gelgitlerde Ay'ın etkisi Güneş'inkinin yaklaşık kaç katıdır?", d: "Yaklaşık 2 katı", y: ["Yaklaşık yarısı", "Yaklaşık 100 katı"], a: "Güneş çok daha kütlelidir ama çok uzaktadır. Gelgit etkisi uzaklıkla çok hızlı azaldığı için yakındaki Ay daha baskındır." },
  { id: "p01-116", k: "Uzay", s: "Gelgitler Dünya'nın kendi ekseni çevresindeki dönüşünü nasıl etkiler?", d: "Çok yavaşça yavaşlatır", y: ["Giderek hızlandırır", "Hiç etkilemez"], a: "Gelgit sürtünmesi günü yüzyılda yaklaşık 2 milisaniye uzatır. Dinozorlar çağında bir gün bugünkünden kısaydı." },
  { id: "p01-117", k: "Uzay", s: "Dünyanın en yüksek gelgitleriyle bilinen yer neresidir?", d: "Kanada'daki Fundy Körfezi", y: ["Marmara Denizi", "Karadeniz kıyıları"], a: "Fundy Körfezi'nde yüksek ve alçak su arasındaki fark 15 metreyi aşabilir. Akdeniz gibi kapalı denizlerde ise gelgit çoğu yerde çok küçüktür." },
  { id: "p01-118", k: "Uzay", s: "Gelgitten yalnız denizler mi etkilenir?", d: "Hayır, katı yer kabuğu da kabarır", y: ["Evet, yalnız denizler etkilenir", "Yalnız göller ve nehirler etkilenir"], a: "Kara gelgiti denen bu etkiyle yer kabuğu günde iki kez onlarca santimetreye kadar yükselip alçalır. Hareket çok yavaş olduğu için hissedilmez." },
  { id: "p01-119", k: "Uzay", s: "Ay'da deprem olur mu?", d: "Evet, ay depremleri kaydedildi", y: ["Hayır, Ay tamamen hareketsizdir", "Yalnız dolunayda olur"], a: "Apollo astronotlarının bıraktığı sismometreler Ay'da sarsıntılar kaydetti. Bunların bir kısmı Dünya'nın gelgit etkisinden kaynaklanır." },
  { id: "p01-120", k: "Uzay", s: "Ay yüzeyini örten ince toz ve kırık kaya tabakasına ne denir?", d: "Regolit", y: ["Magma", "Tundra"], a: "Regolit, milyarlarca yıllık göktaşı çarpmalarıyla oluştu. Keskin taneli olduğu için Apollo astronotlarının giysilerine yapışıp sorun çıkardı." },
  { id: "p01-121", k: "Uzay", s: "Ay'ın kutuplarında hiç Güneş görmeyen kraterlerde ne bulunduğu doğrulandı?", d: "Su buzu", y: ["Sıvı su gölleri", "Altın yatakları"], a: "Bu buz, gelecekte Ay'da kurulacak üsler için içme suyu ve roket yakıtı kaynağı olabilir." },
  { id: "p01-122", k: "Uzay", s: "Ay'ın Dünya çevresindeki yörüngesi hangi şekildedir?", d: "Hafif basık bir elips", y: ["Kusursuz bir çember", "Sekiz biçiminde"], a: "Bu yüzden Ay'ın Dünya'ya uzaklığı yaklaşık 363 bin ile 405 bin kilometre arasında değişir." },
  { id: "p01-123", k: "Uzay", s: "Dünya'nın kaç kalıcı doğal uydusu vardır?", d: "Bir", y: ["İki", "Üç"], a: "Dünya'nın tek kalıcı uydusu Ay'dır. Bazen küçük asteroitler kısa süreliğine Dünya'nın çevresine yakalanıp 'mini ay' gibi dolanabilir." },
  { id: "p01-124", k: "Uzay", s: "Ay'dan bakan biri Dünya'nın da evrelerini görür mü?", d: "Evet, Ay'ın evrelerinin tersini", y: ["Hayır, Dünya hep tam görünür", "Hayır, Dünya hiç görünmez"], a: "Dünya'da Yeni Ay varken Ay'dan bakan biri 'dolu Dünya' görür. Ay'ın yakın yüzünden Dünya gökte hep aşağı yukarı aynı yerde durur." },
  { id: "p01-125", k: "Uzay", s: "Hilal evresinde Ay'ın karanlık kısmının soluk biçimde görünmesine ne neden olur?", d: "Dünya'dan yansıyan Güneş ışığı", y: ["Ay'daki volkanların ışığı", "Yıldızların ışığı"], a: "Bu olaya Dünya ışığı denir. Leonardo da Vinci bunu 1500'lerin başında doğru biçimde açıklamıştı." },
  { id: "p01-126", k: "Uzay", s: "Ay ufka yakınken neden daha büyük görünür?", d: "Bir göz yanılsamasıdır", y: ["O sırada Dünya'ya daha yakındır", "Atmosfer onu büyüteç gibi büyütür"], a: "Ölçüldüğünde ufuktaki Ay tepedekinden büyük değildir. 'Ay yanılsaması' denen bu etkinin nedeni hâlâ tam açıklanamamıştır." },
  { id: "p01-127", k: "Uzay", s: "Apollo görevleri Dünya'ya yaklaşık ne kadar Ay kayası ve toprağı getirdi?", d: "Yaklaşık 380 kilogram", y: ["Yaklaşık 3 kilogram", "Yaklaşık 38 ton"], a: "Bu örnekler Ay'ın yaşının ve oluşumunun anlaşılmasında çok önemli oldu. Sovyet Luna araçları da robotlarla az miktarda örnek getirdi." },
  { id: "p01-128", k: "Uzay", s: "Astronotların Ay'da tekerlekli araç (Ay gezgini) kullandığı ilk görev hangisidir?", d: "Apollo 15", y: ["Apollo 11", "Apollo 8"], a: "Ay gezgini sayesinde astronotlar iniş yerinden kilometrelerce uzaklaşabildi. Bu araçlar bugün hâlâ Ay yüzeyinde duruyor." },
  { id: "p01-129", k: "Uzay", s: "Ay'ın çevresinde dolanan ilk insanlı uzay aracı hangisidir?", d: "Apollo 8", y: ["Apollo 11", "Vostok 1"], a: "Apollo 8 mürettebatı 1968'de Ay'ın çevresinde dolandı. Ünlü 'Dünya'nın doğuşu' fotoğrafı bu görevde çekildi." },
  { id: "p01-130", k: "Uzay", s: "Ay'a ilk yumuşak inişi yapan uzay aracı hangisidir?", d: "Luna 9", y: ["Apollo 11", "Chang'e 4"], a: "Sovyet aracı Luna 9 1966'da Ay'a indi ve yüzeyden ilk fotoğrafları gönderdi. Böylece yüzeyin bir aracı taşıyabildiği anlaşıldı." },
  { id: "p01-131", k: "Uzay", s: "Mars neden kızıl görünür?", d: "Yüzeyindeki demir oksit (pas) yüzünden", y: ["Yüzeyi akan lavla kaplı olduğu için", "Güneş'e çok yakın olduğu için"], a: "Mars'ın tozu ve kayaları demir mineralleri bakımından zengindir. Paslanmış demir gezegene kızıl rengini verir." },
  { id: "p01-132", k: "Uzay", s: "Mars'ın kaç doğal uydusu vardır?", d: "İki", y: ["Bir", "Hiç yok"], a: "Uyduların adı Phobos ve Deimos'tur. İkisi de küçük ve düzensiz biçimlidir; görünüşleri asteroitlere benzer." },
  { id: "p01-133", k: "Uzay", s: "Mars'ın uyduları Phobos ve Deimos'un adları ne anlama gelir?", d: "Korku ve Dehşet", y: ["Gece ve Gündüz", "Ateş ve Su"], a: "Mars, Roma'nın savaş tanrısıdır. Uydular, Yunan mitolojisinde savaş tanrısı Ares'in iki oğlunun adlarını taşır." },
  { id: "p01-134", k: "Uzay", s: "Güneş Sistemi'nin bilinen en büyük volkanı Olympus Mons nerededir?", d: "Mars'ta", y: ["Venüs'te", "Io'da"], a: "Olympus Mons'un yüksekliği yaklaşık 22 kilometredir; Everest'in yaklaşık iki buçuk katı." },
  { id: "p01-135", k: "Uzay", s: "Mars'taki dev kanyon sistemi Valles Marineris yaklaşık ne uzunluktadır?", d: "Yaklaşık 4.000 km", y: ["Yaklaşık 40 km", "Yaklaşık 400 km"], a: "Bu kanyon Dünya'da olsaydı ABD'yi bir kıyıdan öbür kıyıya geçerdi. Yer yer 7 kilometre derinliğe ulaşır." },
  { id: "p01-136", k: "Uzay", s: "Mars'ta bir gün (sol) yaklaşık ne kadar sürer?", d: "Yaklaşık 24 saat 40 dakika", y: ["Yaklaşık 10 saat", "Yaklaşık 58 Dünya günü"], a: "Mars'ın günü Dünya'nınkine çok yakındır. Mars görevlerindeki ekipler bu yüzden zaman zaman 'Mars saatine' göre çalışır." },
  { id: "p01-137", k: "Uzay", s: "Mars'ta bir yıl yaklaşık kaç Dünya günü sürer?", d: "Yaklaşık 687 gün", y: ["Yaklaşık 365 gün", "Yaklaşık 88 gün"], a: "Mars yılı Dünya yılının neredeyse iki katıdır. Bu yüzden Mars'taki mevsimler de Dünya'dakilerden uzundur." },
  { id: "p01-138", k: "Uzay", s: "Mars'taki kütleçekimi Dünya'dakinin yaklaşık ne kadarıdır?", d: "Yaklaşık yüzde 38'i", y: ["Yaklaşık yüzde 90'ı", "Yaklaşık yüzde 5'i"], a: "Dünya'da 100 kilogram gelen biri Mars'ta kendini yaklaşık 38 kilogram gibi hisseder." },
  { id: "p01-139", k: "Uzay", s: "Mars'ın atmosferi Dünya'nınkiyle karşılaştırıldığında nasıldır?", d: "Çok daha incedir", y: ["Çok daha yoğundur", "Neredeyse aynıdır"], a: "Mars'ta yüzey basıncı Dünya'dakinin yüzde 1'inden azdır ve atmosferin büyük kısmı karbondioksittir." },
  { id: "p01-140", k: "Uzay", s: "Mars'ın kutuplarındaki beyaz başlıklar neyden oluşur?", d: "Su buzu ve donmuş karbondioksit", y: ["Tuz yatakları", "Beyaz kum"], a: "Kışın atmosferdeki karbondioksitin bir kısmı donarak kutuplarda kuru buz olarak birikir. Yazın bu katman kısmen buharlaşır." },
  { id: "p01-141", k: "Uzay", s: "Mars'ta mevsimler olur mu?", d: "Evet, ekseni Dünya'nınki gibi eğik", y: ["Hayır, ekseni hiç eğik değil", "Hayır, hep yaz yaşanır"], a: "Mars'ın eksen eğikliği yaklaşık 25 derecedir. Yörüngesi Dünya'nınkinden daha basık olduğu için mevsimlerin uzunlukları birbirinden farklıdır." },
  { id: "p01-142", k: "Uzay", s: "Mars'ta zaman zaman bütün gezegeni saran olay hangisidir?", d: "Toz fırtınaları", y: ["Kar fırtınaları", "Sağanak yağmurlar"], a: "Bazı toz fırtınaları haftalarca sürüp gezegenin tamamını kaplar. 2018'deki böyle bir fırtına, güneş enerjili Opportunity gezginini sonsuza dek susturdu." },
  { id: "p01-143", k: "Uzay", s: "Mars'ta gün batımı hangi renkte görünür?", d: "Mavimsi", y: ["Kıpkırmızı", "Yeşil"], a: "Mars'taki ince toz, mavi ışığı Güneş'in çevresine doğru saçar. Gündüz gökyüzü ise sarımsı kahverengi görünür." },
  { id: "p01-144", k: "Uzay", s: "Mars'ın uydusu Phobos'u uzak gelecekte ne bekliyor?", d: "Mars'a yaklaşıp parçalanması", y: ["Mars'tan kaçıp uzaklaşması", "Bir gezegene dönüşmesi"], a: "Phobos her yüzyılda Mars'a biraz daha yaklaşıyor. On milyonlarca yıl içinde ya Mars'a çarpacak ya da parçalanıp bir halka oluşturacak." },
  { id: "p01-145", k: "Uzay", s: "Mars'tan bakıldığında Phobos uydusu gökyüzünde nereden doğar?", d: "Batıdan", y: ["Doğudan", "Hiç doğmaz, hep sabit durur"], a: "Phobos, Mars'ın çevresindeki turunu 8 saatten kısa sürede tamamlar; Mars'ın kendi dönüşünden çok daha hızlıdır. Bu yüzden batıdan doğar ve günde iki kez gökyüzünü geçer." },
  { id: "p01-146", k: "Uzay", s: "Mars'ın çapı Dünya'nınkinin yaklaşık ne kadarıdır?", d: "Yaklaşık yarısı", y: ["Yaklaşık iki katı", "Yaklaşık onda biri"], a: "Mars'ın çapı yaklaşık 6.800 kilometredir. Kütlesi ise Dünya'nın yalnız onda biri kadardır." },
  { id: "p01-147", k: "Uzay", s: "Mars'ın ortalama yüzey sıcaklığı yaklaşık kaç derecedir?", d: "Yaklaşık eksi 60 °C", y: ["Yaklaşık 15 °C", "Yaklaşık eksi 200 °C"], a: "Ekvatorda yaz öğleninde sıcaklık 20 °C'ye çıkabilir, kutuplarda ise eksi 150 °C'nin altına inebilir." },
  { id: "p01-148", k: "Uzay", s: "Mars'ta geçmişte sıvı su bulunduğunu gösteren kanıtlardan biri hangisidir?", d: "Kurumuş nehir yatakları ve deltalar", y: ["Yüzeydeki yeşil bitki örtüsü", "Bugün akan büyük nehirler"], a: "Perseverance gezgininin indiği Jezero krateri, eskiden bir göle dökülen nehrin deltasını barındırır." },
  { id: "p01-149", k: "Uzay", s: "Mars'ın yüzeyinde su neden uzun süre sıvı hâlde kalamaz?", d: "Hava basıncı çok düşük, hava çok soğuk", y: ["Mars'ın kütleçekimi suyu uzaya fırlatır", "Mars'ın yüzeyi suyu anında emer"], a: "Bu koşullarda su ya donar ya da hızla buharlaşır. Mars'taki suyun çoğu bugün kutuplarda ve toprağın altında buz olarak bulunur." },
  { id: "p01-150", k: "Uzay", s: "Mars yüzeyinde gezinen ilk tekerlekli araç (gezgin) hangisidir?", d: "Sojourner", y: ["Curiosity", "Perseverance"], a: "Mikrodalga fırın büyüklüğündeki Sojourner, 1997'de Mars Pathfinder göreviyle Mars'a indi." },
  { id: "p01-151", k: "Uzay", s: "Başka bir gezegende motorlu ve kontrollü uçuş yapan ilk araç hangisidir?", d: "Ingenuity helikopteri", y: ["Curiosity gezgini", "Viking 1 iniş aracı"], a: "Ingenuity 2021'de Mars'ta havalandı. Yalnız 5 deneme uçuşu planlanmıştı ama 70'ten fazla uçuş yaptı." },
  { id: "p01-152", k: "Uzay", s: "Curiosity gezgini 2012'de Mars'ta hangi kratere indi?", d: "Gale krateri", y: ["Jezero krateri", "Olympus Mons"], a: "Curiosity, kraterin ortasında yükselen Sharp Dağı'nın kaya katmanlarını tırmanarak Mars'ın geçmişini inceliyor." },
  { id: "p01-153", k: "Uzay", s: "Perseverance gezgini Mars'a hangi yıl indi?", d: "2021", y: ["1997", "2012"], a: "Perseverance, eski bir göl yatağı olan Jezero krateri'nde geçmiş yaşam izi arıyor ve kaya örneklerini tüplerde saklıyor." },
  { id: "p01-154", k: "Uzay", s: "Mars'a gitmek için uygun fırlatma fırsatları yaklaşık ne sıklıkla doğar?", d: "Yaklaşık her 26 ayda bir", y: ["Her ay", "Her 10 yılda bir"], a: "Dünya ile Mars uygun konuma ancak bu aralıklarla gelir. Uzay ajansları Mars araçlarını bu yüzden genellikle aynı yıllarda fırlatır." },
  { id: "p01-155", k: "Uzay", s: "Dünya'da Mars'tan gelmiş kaya parçası var mıdır?", d: "Evet, göktaşı olarak düşenler var", y: ["Hayır, hiç yoktur", "Yalnız astronotların getirdikleri var"], a: "Mars'a çarpan büyük cisimler yüzeyden kaya parçaları kopardı ve bunların bir kısmı Dünya'ya düştü. İçlerinde hapsolan gaz Mars atmosferiyle aynıdır." },
  { id: "p01-156", k: "Uzay", s: "Mars'ın yakından ilk fotoğraflarını çeken uzay aracı hangisidir?", d: "Mariner 4", y: ["Apollo 11", "Voyager 1"], a: "Mariner 4, 1965'te Mars'ın yanından geçti ve kraterli bir yüzey gösterdi. Bu fotoğraflar Mars'ta kanallar kazan bir uygarlık olduğu düşüncesine son verdi." },
  { id: "p01-157", k: "Uzay", s: "Mars yüzeyinden ilk renkli fotoğrafları gönderen NASA iniş araçları hangileridir?", d: "Viking 1 ve Viking 2", y: ["Apollo 1 ve Apollo 2", "Voyager 1 ve Voyager 2"], a: "Viking araçları 1976'da Mars'a indi. Toprakta yaşam izi arayan deneyler de yaptılar." },
  { id: "p01-158", k: "Uzay", s: "Güneş'ten uzaklık sırasına göre Mars kaçıncı gezegendir?", d: "Dördüncü", y: ["Üçüncü", "Beşinci"], a: "Mars, Dünya'nın hemen dışındaki komşumuzdur ve kayalık gezegenlerin en dıştakidir." },
  { id: "p01-159", k: "Uzay", s: "Mars yörüngesine ilk denemesinde ulaşan ilk ülke hangisidir?", d: "Hindistan", y: ["Çin", "Japonya"], a: "Hindistan'ın Mangalyaan aracı 2014'te Mars yörüngesine girdi. Görev, düşük bütçesiyle de dikkat çekti." },
  { id: "p01-160", k: "Uzay", s: "2008'de Mars'ın kuzey kutup bölgesine inip toprağın hemen altında buz bulan araç hangisidir?", d: "Phoenix", y: ["Sojourner", "Spirit"], a: "Phoenix'in kazdığı çukurlarda görülen beyaz parçalar birkaç gün içinde buharlaşıp kayboldu. Bu, onların su buzu olduğunu gösterdi." },
  { id: "p01-161", k: "Uzay", s: "Mars gece gökyüzünde çıplak gözle nasıl görünür?", d: "Kızıl renkli bir yıldız gibi", y: ["Ay kadar büyük bir disk gibi", "Yeşil renkli bir yıldız gibi"], a: "Mars yaklaşık iki yılda bir Dünya'ya yaklaşır ve o dönemde çok parlak görünür. Ay kadar büyük görüneceği iddiası her yıl yayılan bir şehir efsanesidir." },
  { id: "p01-162", k: "Uzay", s: "90 gün çalışması planlanan Opportunity gezgini Mars'ta yaklaşık ne kadar çalıştı?", d: "Yaklaşık 15 yıl", y: ["Yaklaşık 9 ay", "Yaklaşık 3 yıl"], a: "Opportunity 2004'te Mars'a indi ve bir maraton mesafesinden uzun yol kat etti. Rüzgâr zaman zaman güneş panellerini temizleyerek ömrünü uzattı." },
  { id: "p01-163", k: "Uzay", s: "Asteroit kuşağı hangi iki gezegenin yörüngeleri arasındadır?", d: "Mars ile Jüpiter", y: ["Dünya ile Mars", "Satürn ile Uranüs"], a: "Kuşakta çok sayıda kaya parçası Güneş'in çevresinde dolanır. Yine de hepsinin toplam kütlesi Ay'ınkinin küçük bir kısmıdır." },
  { id: "p01-164", k: "Uzay", s: "Asteroit kuşağından geçen uzay araçları neden asteroitlere çarpmaz?", d: "Asteroitler birbirinden çok uzaktır", y: ["Araçlar kalkanla korunur", "Asteroitler araçlardan kaçar"], a: "Filmlerdeki sık asteroit alanlarının aksine kuşaktaki cisimler arasında çoğu zaman yüz binlerce kilometre vardır. Pek çok araç kuşağı sorunsuz geçti." },
  { id: "p01-165", k: "Uzay", s: "Asteroit kuşağındaki en büyük cisim hangisidir?", d: "Ceres", y: ["Vesta", "Phobos"], a: "Ceres kendi kütleçekimiyle küre biçimini alacak kadar büyüktür. Bu yüzden 2006'dan beri cüce gezegen sayılır." },
  { id: "p01-166", k: "Uzay", s: "İlk asteroit Ceres hangi yıl keşfedildi?", d: "1801", y: ["1610", "1930"], a: "İtalyan gökbilimci Giuseppe Piazzi, Ceres'i 1801'in ilk gecesinde buldu. Önce gezegen sanıldı, sonra asteroitler arasında sayıldı." },
  { id: "p01-167", k: "Uzay", s: "Dawn uzay aracı hangi iki gök cismini yörüngeden inceledi?", d: "Vesta ve Ceres", y: ["Ay ve Mars", "Phobos ve Deimos"], a: "Dawn, iki ayrı gök cisminin yörüngesine giren ilk araçtır. Bunu yakıt tasarruflu iyon motoru sayesinde başardı." },
  { id: "p01-168", k: "Uzay", s: "Ana kuşakta, Dünya'dan bakıldığında en parlak görünen asteroit hangisidir?", d: "Vesta", y: ["Ceres", "Eros"], a: "Vesta, en uygun konumlarında karanlık bir gökyüzünde çıplak gözle zor da olsa seçilebilir. Güney yarımküresinde dev bir çarpma havzası vardır." },
  { id: "p01-169", k: "Uzay", s: "Jüpiter'le aynı yörüngede, onun önünde ve arkasında dolanan asteroitlere ne denir?", d: "Truva asteroitleri", y: ["Kuiper cisimleri", "Oort cisimleri"], a: "Bu asteroitler, Jüpiter ile Güneş'in çekiminin dengelendiği bölgelerde toplanır. NASA'nın Lucy aracı onları incelemek için yola çıktı." },
  { id: "p01-170", k: "Uzay", s: "Yaklaşık 66 milyon yıl önceki büyük yok oluşla en çok ilişkilendirilen olay hangisidir?", d: "Dev bir asteroit çarpması", y: ["Bir buzul çağının başlaması", "Ay'ın Dünya'ya yaklaşması"], a: "Çarpmanın izi Meksika'nın Yucatán Yarımadası'nda gömülü Chicxulub kraterinde bulunur. Kuşlar dışındaki dinozorlar bu dönemde yok oldu." },
  { id: "p01-171", k: "Uzay", s: "NASA'nın DART görevi 2022'de neyi başardı?", d: "Bir asteroidin yörüngesini değiştirdi", y: ["Bir asteroide insan indirdi", "Bir asteroidi parçalayıp yok etti"], a: "DART aracı, Dimorphos adlı küçük asteroide bilerek çarpıp yörüngesini kısalttı. Bu, gezegen savunması için ilk gerçek denemeydi." },
  { id: "p01-172", k: "Uzay", s: "Bir asteroitten Dünya'ya ilk kez örnek getiren ülke hangisidir?", d: "Japonya", y: ["ABD", "Hindistan"], a: "Japonya'nın Hayabusa aracı 2010'da Itokawa asteroidinden toz taneleri getirdi. Hayabusa2 de 2020'de Ryugu'dan örnek getirdi." },
  { id: "p01-173", k: "Uzay", s: "NASA'nın OSIRIS-REx aracı hangi asteroitten örnek getirdi?", d: "Bennu", y: ["Ceres", "Vesta"], a: "Örnek kapsülü 2023'te Dünya'ya indi. Bennu örneklerinde su içeren mineraller ve karbon bakımından zengin maddeler bulundu." },
  { id: "p01-174", k: "Uzay", s: "Uzayda dolanan küçük kaya ya da metal parçasına ne denir?", d: "Meteoroid", y: ["Meteorit", "Kuyruklu yıldız"], a: "Meteoroid atmosfere girip yanarken oluşan ışık çizgisine meteor, yere ulaşan parçasına ise meteorit denir." },
  { id: "p01-175", k: "Uzay", s: "Halk arasında 'kayan yıldız' denen ışık çizgisi aslında nedir?", d: "Atmosferde yanan bir meteor", y: ["Yerinden kopan bir yıldız", "Patlayan bir yıldız"], a: "Bu ışık çizgilerinin yıldızlarla ilgisi yoktur. Çoğu, kum tanesi büyüklüğündeki bir toz parçasının atmosferde yanmasıyla oluşur." },
  { id: "p01-176", k: "Uzay", s: "1908'de Sibirya'da milyonlarca ağacı deviren olay hangisidir?", d: "Tunguska olayı", y: ["Çelyabinsk olayı", "Çernobil kazası"], a: "Bir göktaşı yere çarpmadan havada patladı ve yaklaşık 2.000 kilometrekarelik ormanı yerle bir etti. Bölgede büyük bir krater bulunmadı." },
  { id: "p01-177", k: "Uzay", s: "2013'te Rusya'nın Çelyabinsk kentinde yaklaşık 1.500 kişinin yaralanmasına ne yol açtı?", d: "Havada patlayan bir göktaşı", y: ["Düşen bir uydu", "Bir yanardağ patlaması"], a: "Yaklaşık 20 metrelik göktaşının atmosferdeki patlaması binlerce binanın camını kırdı. Yaralananların çoğu cam kırıklarından etkilendi." },
  { id: "p01-178", k: "Uzay", s: "2029'da Dünya'nın çok yakınından geçecek ünlü asteroit hangisidir?", d: "Apophis", y: ["Ceres", "Vesta"], a: "Apophis, 13 Nisan 2029'da bazı iletişim uydularından daha yakından geçecek. Hesaplar, bu geçişte Dünya'ya çarpmayacağını gösteriyor." },
  { id: "p01-179", k: "Uzay", s: "Psyche adlı asteroit bilim insanlarının ilgisini neden çekiyor?", d: "Büyük ölçüde metalden oluşabilir", y: ["Üzerinde su okyanusu var", "Dünya'ya çarpması bekleniyor"], a: "Psyche'nin eski bir gezegen çekirdeğinin kalıntısı olabileceği düşünülüyor. NASA'nın aynı adlı aracı onu incelemek için 2023'te yola çıktı." },
  { id: "p01-180", k: "Uzay", s: "Arizona'daki ünlü Barringer (Meteor) Krateri nasıl oluştu?", d: "Bir göktaşının çarpmasıyla", y: ["Bir yanardağın çökmesiyle", "Rüzgâr aşındırmasıyla"], a: "Krater yaklaşık 50 bin yıl önce oluştu ve çapı 1 kilometreyi aşar. Dünya'nın en iyi korunmuş çarpma kraterlerinden biridir." },
  { id: "p01-181", k: "Uzay", s: "Asteroitlerin çoğu hangi şekildedir?", d: "Düzensiz, patates benzeri", y: ["Kusursuz küre", "Düz bir disk"], a: "Küçük cisimlerin kütleçekimi kendilerini küre biçimine sokmaya yetmez. Bu yüzden çoğu asteroit yamru yumru görünür." },
  { id: "p01-182", k: "Uzay", s: "Bazı asteroitlerin kendi uydusu olabilir mi?", d: "Evet, uydulu asteroitler bilinir", y: ["Hayır, kütleleri buna yetmez", "Yalnız Jüpiter'e yakın olanların olur"], a: "İlk örnek, 1993'te Galileo aracının görüntülediği Ida asteroidinin küçük uydusu Dactyl'dir. DART'ın çarptığı Dimorphos da Didymos'un uydusudur." },
  { id: "p01-183", k: "Uzay", s: "Bir asteroide iniş yapan ilk uzay aracı hangisidir?", d: "NEAR Shoemaker", y: ["Voyager 2", "Cassini"], a: "NEAR Shoemaker, Eros asteroidinin yörüngesinde bir yıl kaldıktan sonra 2001'de yüzeyine indi. Aslında iniş için tasarlanmamıştı." },
  { id: "p01-184", k: "Uzay", s: "Dünya'ya düşen meteoritlerin çoğu hangi türdendir?", d: "Taşlı meteoritler", y: ["Demir meteoritler", "Buz meteoritler"], a: "Düşüşü görülen meteoritlerin büyük çoğunluğu taşlıdır. Demir meteoritler daha seyrek düşer ama kolay tanındıkları için koleksiyonlarda çoktur." },
  { id: "p01-185", k: "Uzay", s: "Meteorit arayan bilim insanları neden sık sık Antarktika'ya gider?", d: "Koyu taşlar beyaz buzda kolay görülür", y: ["Kutuplara daha çok göktaşı düşer", "Manyetik alan göktaşlarını oraya çeker"], a: "Buz akıntıları göktaşlarını bazı bölgelerde yüzeye taşıyıp biriktirir. Bilinen meteoritlerin büyük bölümü Antarktika'da bulundu." },
  { id: "p01-186", k: "Uzay", s: "Bilinen en büyük tek parça meteorit olan Hoba hangi ülkededir?", d: "Namibya", y: ["Rusya", "Meksika"], a: "Hoba yaklaşık 60 ton ağırlığında demir-nikel bir kütledir. Çok ağır olduğu için bulunduğu yerde duruyor." },
  { id: "p01-187", k: "Uzay", s: "Meteorların çoğu neden yere ulaşmadan kaybolur?", d: "Atmosferde ısınıp buharlaştıkları için", y: ["Manyetik alan onları geri ittiği için", "Ay onları yolundan çektiği için"], a: "Meteorlar atmosfere çok hızlı girer, önlerindeki havayı sıkıştırıp ısıtır. Küçük parçalar bu ısıyla tamamen buharlaşır." },
  { id: "p01-188", k: "Uzay", s: "Meteorlar genellikle yaklaşık hangi yükseklikte parlamaya başlar?", d: "Yaklaşık 100 km", y: ["Yaklaşık 1 km", "Yaklaşık 10.000 km"], a: "Bu yükseklik yolcu uçaklarının uçtuğu irtifanın yaklaşık on katıdır. Meteorlar atmosfere saniyede onlarca kilometre hızla girer." },
  { id: "p01-189", k: "Uzay", s: "Venüs'ten bile parlak görünen meteorlara ne ad verilir?", d: "Ateş topu", y: ["Süpernova", "Kutup ışığı"], a: "Ateş toplarının bazıları gündüz bile görülebilir. Bazen arkalarında dakikalarca kalan bir duman izi bırakırlar." },
  { id: "p01-190", k: "Uzay", s: "Meteor yağmurları neden her yıl aşağı yukarı aynı tarihlerde görülür?", d: "Dünya her yıl aynı toz izinden geçer", y: ["Ay her yıl aynı yerde durur", "Güneş her yıl taş fırlatır"], a: "Kuyruklu yıldızlar yörüngeleri boyunca toz bırakır. Dünya bu izin içinden her yıl aynı dönemde geçer ve meteor sayısı artar." },
  { id: "p01-191", k: "Uzay", s: "Her yıl Ağustos'ta zirve yapan ünlü meteor yağmuru hangisidir?", d: "Perseidler", y: ["Geminidler", "Leonidler"], a: "Perseidler, Swift-Tuttle kuyruklu yıldızının bıraktığı tozdan oluşur. Karanlık bir yerden saatte onlarca meteor görülebilir." },
  { id: "p01-192", k: "Uzay", s: "Aralık'ta zirve yapan Geminid meteor yağmurunun kaynağı nedir?", d: "3200 Phaethon adlı bir asteroit", y: ["Halley kuyruklu yıldızı", "Ay'dan kopan parçalar"], a: "Meteor yağmurlarının çoğu kuyruklu yıldızlardan kaynaklanır. Geminidler ise kaynağı bir asteroit olan ender yağmurlardandır." },
  { id: "p01-193", k: "Uzay", s: "Meteor yağmurları adlarını nereden alır?", d: "Geliyor gibi göründükleri takımyıldızdan", y: ["Onları ilk gören kişiden", "Görüldükleri aydan"], a: "Bu noktaya ışınım noktası (radyant) denir. Örneğin Perseidler Perseus, Geminidler İkizler takımyıldızından geliyor gibi görünür." },
  { id: "p01-194", k: "Uzay", s: "Halley kuyruklu yıldızının bıraktığı tozdan oluşan meteor yağmuru hangisidir?", d: "Orionidler", y: ["Perseidler", "Geminidler"], a: "Dünya, Halley'nin yörüngesini yılda iki kez keser. Mayıs'taki Eta Akuaridler de aynı kuyruklu yıldızın tozundan oluşur." },
  { id: "p01-195", k: "Uzay", s: "Dünya'nın yörüngesine yaklaşan asteroit ve kuyruklu yıldızlara genel olarak ne denir?", d: "Dünya'ya yakın cisimler", y: ["Truva cisimleri", "Kuiper cisimleri"], a: "Gökbilimciler bu cisimleri teleskoplarla düzenli olarak tarar ve yörüngelerini hesaplar. Amaç olası bir tehlikeyi yıllar önceden görebilmektir." },
  { id: "p01-196", k: "Uzay", s: "Bir yılda en az kaç Güneş tutulması olur?", d: "En az iki", y: ["Hiç olmayabilir", "En az on"], a: "Her yıl en az iki, en fazla beş Güneş tutulması yaşanır. Ama çoğu parçalı ya da halkalıdır ve yalnız belli bölgelerden görülür." },
  { id: "p01-197", k: "Uzay", s: "Parçalı Güneş tutulması nedir?", d: "Ay'ın Güneş'in bir kısmını örtmesi", y: ["Güneş'in bir kısmının sönmesi", "Dünya'nın Ay'ı kısmen örtmesi"], a: "Parçalı tutulmada Güneş, sanki bir lokma alınmış gibi görünür. Bu sırada da Güneş'e özel gözlük olmadan bakmak tehlikelidir." },
  { id: "p01-198", k: "Uzay", s: "Tam Ay tutulması neden tam Güneş tutulmasından çok daha uzun sürer?", d: "Dünya'nın gölgesi çok daha büyük olduğu için", y: ["Ay o sırada durduğu için", "Gece gündüzden uzun olduğu için"], a: "Tam Ay tutulmasında tam evre bir saati aşabilir. Tam Güneş tutulmasının tam evresi ise en fazla birkaç dakikadır." },
  { id: "p01-199", k: "Uzay", s: "Dünya'da çarpma kraterleri neden Ay'dakinden çok daha azdır?", d: "Aşınma ve yer hareketleri izleri siler", y: ["Dünya'ya hiç göktaşı düşmez", "Manyetik alan göktaşlarını iter"], a: "Rüzgâr, su, yanardağlar ve levha hareketleri eski kraterleri zamanla siler. Ay'da bu süreçler olmadığı için milyarlarca yıllık kraterler korunur." },
  { id: "p01-200", k: "Uzay", s: "Asteroitleri kuyruklu yıldızlardan ayıran temel fark nedir?", d: "Kuyruklu yıldızlar çok daha fazla buz içerir", y: ["Asteroitler Güneş'in çevresinde dolanmaz", "Kuyruklu yıldızlar aslında yıldızdır"], a: "Kuyruklu yıldızlar Güneş'e yaklaşınca buzları buharlaşır ve kuyruk oluşur. Asteroitler ise çoğunlukla kaya ve metalden oluşur." },
];
